import { resolveCidrs, isOpenCidr } from './sg-cidr-aggregator.js';
import { isIcmpProtocol, assignAzurePriority, assignGcpPriority } from './sg-rule-comparator.js';

// Keys we explicitly handle during mapping
const MAPPED_KEYS: readonly string[] = [
  'description',
  'egress',
  'ingress',
  'name',
  'tags',
  'vpc_id',
];

// ---------------------------------------------------------------------------
// Rule type definitions
// ---------------------------------------------------------------------------

export interface SgRule {
  readonly cidr_blocks?: readonly string[];
  readonly ipv6_cidr_blocks?: readonly string[];
  readonly description?: string;
  readonly from_port?: number;
  readonly to_port?: number;
  readonly protocol?: string;
  readonly self?: boolean;
  readonly source_security_group_id?: string;
  readonly prefix_list_ids?: readonly string[];
}

// ---------------------------------------------------------------------------
// Blocker gate: detect overly permissive rules
// ---------------------------------------------------------------------------

function hasOverlyPermissiveRule(rules: readonly SgRule[]): boolean {
  for (const rule of rules) {
    const resolved = resolveCidrs(rule);
    if (!isOpenCidr(resolved)) continue;

    // Protocol -1 means all traffic
    if (rule.protocol === '-1') return true;

    // Port range 0-65535 means all ports
    if (rule.from_port === 0 && rule.to_port === 65535) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Findings helpers for special CIDR fields
// ---------------------------------------------------------------------------

function emitCidrFindings(resourceId: string, rule: SgRule): TranslationFinding[] {
  const findings: TranslationFinding[] = [];
  const resolved = resolveCidrs(rule);

  if (resolved.hasSelf) {
    findings.push(
      createFinding(
        resourceId,
        'warning',
        'SG_SELF_REFERENCE',
        'Security group rule references "self"; manual review required to translate self-referencing rules',
      ),
    );
  }

  if (resolved.hasSourceSgRef !== null) {
    findings.push(
      createFinding(
        resourceId,
        'warning',
        'SG_CROSS_SG_REFERENCE',
        `Security group rule references another security group (${resolved.hasSourceSgRef}); cross-SG references require manual wiring`,
      ),
    );
  }

  return findings;
}

// ---------------------------------------------------------------------------
