// ---------------------------------------------------------------------------
// Protocol / port helpers
// ---------------------------------------------------------------------------

function mapProtocolAzure(protocol: string | undefined): string {
  if (!protocol || protocol === '-1') return '*';
  const upper = protocol.toUpperCase();
  if (upper === 'TCP') return 'Tcp';
  if (upper === 'UDP') return 'Udp';
  if (upper === 'ICMP') return 'Icmp';
  return '*';
}

function mapProtocolGcp(protocol: string | undefined): string {
  if (!protocol || protocol === '-1') return 'all';
  return protocol.toLowerCase();
}

function formatPortRange(from: number | undefined, to: number | undefined): string {
  if (from === undefined && to === undefined) return '*';
  if (from === to) return String(from ?? 0);
  return `${from ?? 0}-${to ?? 65535}`;
}

function formatGcpPorts(from: number | undefined, to: number | undefined): string[] {
  if (from === undefined && to === undefined) return [];
  if (from === to) return [String(from ?? 0)];
  return [`${from ?? 0}-${to ?? 65535}`];
}

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/**
 * Translates an aws_security_group to Azure NSG+rules or GCP firewall rules.
 * Applies the BLOCKER GATE for overly permissive rules before translation.
 */
export function translateSecurityGroup(ctx: TranslationContext): EngineResult {
  const attrs = ctx.resource.attributes as Record<string, unknown>;

  // BLOCKER GATE: ingress-only check for overly permissive rules
  const ingress = (attrs['ingress'] as readonly SgRule[] | undefined) ?? [];
  const egress = (attrs['egress'] as readonly SgRule[] | undefined) ?? [];

  if (hasOverlyPermissiveRule(ingress)) {
    return {
      translated: [],
      findings: [
        createFinding(
          ctx.resource.id,
          'blocker',
          'SECURITY_GROUP_RULE_BROADENING',
          'Security group contains an overly permissive ingress rule (0.0.0.0/0 or ::/0 with all protocols or all ports); manual review required',
        ),
      ],
    };
  }

  // Egress warning (not blocker) for overly permissive egress
  const egressWarnings: TranslationFinding[] = [];
  if (hasOverlyPermissiveRule(egress)) {
    egressWarnings.push(
      createFinding(
        ctx.resource.id,
        'warning',
        'SG_EGRESS_OPEN',
        'Security group contains an overly permissive egress rule (0.0.0.0/0 or ::/0 with all protocols or all ports); review recommended',
      ),
    );
  }

  const result = ctx.targetProvider === 'azure'
    ? translateToAzure(ctx)
    : translateToGcp(ctx);

  // Merge egress warnings into findings
  if (egressWarnings.length > 0) {
    return {
      translated: result.translated,
      findings: [...egressWarnings, ...result.findings],
    };
  }

  return result;
}
